package io.whozoss.factory.delivery.persistence

import org.springframework.data.neo4j.core.schema.Id
import org.springframework.data.neo4j.core.schema.Node
import java.time.Instant

/**
 * Spring Data Neo4j projection of one append-only delivery journal entry.
 *
 * Replaces the `delivery_journal` PostgreSQL row. The node [id] is
 * `(organizationId, workstreamId, namespaceId, deliveryId, recordSequence)`
 * encoded as a single string; [recordSequence] is the monotone ordering key
 * generated by the adapter as `MAX(recordSequence) + 1`.
 */
@Node("DeliveryRecord")
data class DeliveryRecordNode(
    @Id
    val id: String,
    val organizationId: String,
    val workstreamId: String,
    val namespaceId: String,
    val deliveryId: String,
    val recordSequence: Long,
    val recordId: String,
    val recordType: String? = null,
    val payload: String,
    val createdAt: Instant,
) {
    companion object {
        fun compositeId(
            organizationId: String,
            workstreamId: String,
            namespaceId: String,
            deliveryId: String,
            recordSequence: Long,
        ): String = "$organizationId|$workstreamId|$namespaceId|$deliveryId|$recordSequence"
    }
}
